import{_ as s,o as a,c as p,a2 as n}from"./chunks/framework.BXzK3EA4.js";const o="/assets/%E5%AE%98%E7%BD%91%E8%B4%AD%E4%B9%B0vps.Cx32B2E6.png",l="/assets/%E5%8D%95%E5%87%BBvps.CrSZIphk.png",i="/assets/%E9%80%9A%E8%BF%87%E5%AE%98%E7%BD%91%E7%AB%8B%E5%8D%B3%E8%AE%A2%E8%B4%AD.DdDgfjCx.png",r="/assets/%E8%87%AA%E5%AE%9A%E4%B9%89vps%E9%85%8D%E7%BD%AE.CS89KdjZ.png",e="/assets/vps%E6%8E%A8%E8%8D%90%E4%BA%A7%E5%93%81%E9%85%8D%E7%BD%AE.DRfjz9nl.png",d="/assets/%E7%99%BB%E5%BD%95rak%E5%AE%98%E7%BD%91.Dg4J8-fU.png",g="/assets/%E7%99%BB%E5%BD%95raksmart%E6%8E%A7%E5%88%B6%E5%8F%B0.DGZE5lRz.png",h="/assets/%E8%B4%AD%E4%B9%B0%E4%B8%AD%E5%BF%83vps.C86uD-oC.png",E="/assets/vpsvps.Dzv2PFja.png",c="/assets/%E7%AB%8B%E5%8D%B3%E8%B4%AD%E4%B9%B0vps11.CtyKvKMi.png",m="/assets/vps%E7%A1%AE%E8%AE%A4%E4%BF%A1%E6%81%AF11.CUhopm8v.png",P="/assets/vps%E6%94%AF%E4%BB%98.BYWAPCAd.png",S="/assets/vps%E5%AE%8C%E6%88%90%E7%BB%93%E7%AE%97.BKJiX7Hj.png",_="/assets/%E6%9C%89%E6%95%88%E7%9A%84vps%E6%94%B9%E7%89%88%E5%90%8E.9E52oKjz.png",f=JSON.parse('{"title":"购买 VPS","description":"","frontmatter":{"title":"购买 VPS"},"headers":[],"relativePath":"vps/quickstart/purchase.md","filePath":"vps/quickstart/purchase.md","lastUpdated":1793696072000}'),B={name:"vps/quickstart/purchase.md"};function b(k,t,A,u,V,v){return a(),p("div",null,[...t[0]||(t[0]=[n('<p>本文介绍如何通过 RakSmart 官网 VPS 入口和控制台入口购买 VPS 。</p><hr><h3 id="准备工作" tabindex="-1">准备工作 <a class="header-anchor" href="#准备工作" aria-label="Permalink to &quot;准备工作&quot;">​</a></h3><ol><li><p>注册 RakSmart 账号，详细步骤可参考<a href="https://cn.raksmart.com/login/index.html" target="_blank" rel="noreferrer">注册 RakSmart 账号</a>。</p></li><li><p>为账户充值，确保账户有足够的资金，以免购买产品失败。具体操作，请参考<a href="/beginners-guide/wallet/balance.html#为-raksmart-账号充值">为 RakSmart 账号充值</a>。</p><blockquote><p><strong>说明</strong></p><p>目前仅 VPS 支持小时计费。小时计费会从账户余额中扣款，为了保证业务连续性，请保持余额充足。</p></blockquote></li><li><p>了解 RakSmart 产品和配置项、计费周期、付款方式等信息，参考<a href="/beginners-guide/buy-products/purchase.html">购买 RakSmart 产品</a>)。</p></li></ol><hr><h3 id="通过官网-vps-入口购买" tabindex="-1">通过官网 VPS 入口购买 <a class="header-anchor" href="#通过官网-vps-入口购买" aria-label="Permalink to &quot;通过官网 VPS 入口购买&quot;">​</a></h3><p>您可以直接通过 RakSmart 官网 VPS 入口购买所需配置。</p><hr><h4 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h4><ol><li><p>使用注册的 RakSmart账号登录 <a href="https://cn.raksmart.com/" target="_blank" rel="noreferrer">RakSmart 官网</a>。</p></li><li><p>将鼠标悬停在顶部导航 <strong>VPS</strong>，打开产品下拉列表。</p><p><img src="'+o+'" alt="官网购买vps.png"></p></li><li><p>单击 <strong>VPS</strong>，进入 VPS 产品页面。</p><p><img src="'+l+'" alt="单击vps.png"></p></li><li><p>单击<strong>立即订购</strong>。</p><p><img src="'+i+'" alt="通过官网立即订购.png"></p></li><li><p>在<strong>配置</strong>购物车页面，参考如下信息完成自定义产品配置。各配置项详细说明，请参考<a href="#配置项及付款流程说明">配置项及付款流程说明</a>。</p><p><img src="'+r+'" alt="自定义vps配置.png"></p></li><li><p>（可选）您也可以在上述<strong>VPS的产品页面</strong>，选择一个推荐产品配置，单击<strong>立即购买</strong>。</p><p><img src="'+e+'" alt="vps推荐产品配置.png"></p></li></ol><hr><h3 id="通过控制台入口购买" tabindex="-1">通过控制台入口购买 <a class="header-anchor" href="#通过控制台入口购买" aria-label="Permalink to &quot;通过控制台入口购买&quot;">​</a></h3><p>本文主要介绍通过 RakSmart 控制台购买中心入口购买 VPS 。</p><ol><li><p>使用注册的 RakSmart 账号登录 <a href="https://cn.raksmart.com/login/index.html" target="_blank" rel="noreferrer">RakSmart 官网</a>。</p><p><img src="'+d+'" alt="登录rak官网.png"></p></li><li><p>在顶部导航右侧，单击<strong>控制台</strong>，进入控制台客户中心页面。</p><p><img src="'+g+'" alt="登录raksmart控制台.png"></p></li><li><p>单击<strong>购买中心</strong>，进入<strong>购物车</strong>页面。</p><p><img src="'+h+'" alt="购买中心vps.png"></p></li><li><p>在顶部标签页，单击 <strong>VPS</strong> -&gt; <strong>VPS</strong>，进入<strong>配置</strong>页面。</p><p><img src="'+E+'" alt="vpsvps.png"></p></li><li><p>根据业务需求完成产品配置选择。配置方法和付款流程的详细介绍可参考<a href="#通过官网 VPS 入口购买">通过官网 VPS 入口购买</a>。 <img src="'+r+'" alt="自定义vps配置.png"></p></li></ol><hr><h3 id="配置项及付款流程说明" tabindex="-1">配置项及付款流程说明 <a class="header-anchor" href="#配置项及付款流程说明" aria-label="Permalink to &quot;配置项及付款流程说明&quot;">​</a></h3><ol><li><p>选择地区选项</p><p>选择购买 VPS 的区域、可用区和类型。</p><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th></tr></thead><tbody><tr><td>区域</td><td>请就近选择靠近您业务的区域。VPS 购买后无法更换区域，请谨慎选择。</td></tr><tr><td>可用区</td><td>请就近选择靠近您业务的可用区，可减少网络时延，提高访问速度。VPS 购买后无法更换可用区，请谨慎选择。</td></tr><tr><td>类型</td><td>指服务器的资源分配模式，决定了硬件资源的占用权限。根据您的业务规模和成本预算选择合适的 VPS 类型：<br>- 共享：VPS 实例共享 CPU 资源，成本低但性能易受其他用户影响；<br>- 独享：VPS 实例独占 CPU 资源，性能稳定可控，适合对稳定性要求高的业务。</td></tr></tbody></table></li><li><p>服务器设置</p><p>主机名称与控制台密码默认由系统生成，支持自定义修改。</p></li><li><p>配置选项</p><p>请参考如下信息完成配置<strong>配置选项</strong>。</p><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th></tr></thead><tbody><tr><td>规格</td><td>RakSmart 提供多种类型的 VPS 供您选择，针对不同的应用场景，可以选择不同的规格。</td></tr><tr><td>系统盘</td><td>根据需要选择系统盘的类型。RakSmart 支持的系统盘有两种：<br>- HDD：成本较低，读写速度适中，适合对性能要求不高、预算有限的场景；<br>- NVME：采用高速固态存储技术，读写速度是机械硬盘的数倍，能显著提升系统响应速度，适合对性能要求较高的业务。</td></tr><tr><td>数据盘选项</td><td>用于存储用户数据、日志和其他应用程序等非系统相关的数据。支持配置新数据盘和绑定已有数据盘。</td></tr><tr><td>操作系统</td><td>服务器运行的系统环境，可选类型包括：<br>- Linux 系统：CentOS、 Ubuntu、Debian、Rocky、Almalinux；<br>- Windows 系统：Windows Server Datacenter 版本。</td></tr><tr><td>带宽类型</td><td>服务器接入的公网线路类型，包含大陆优化 VIP、精品 CN2 和国际 BGP，分别针对中国访问优化、跨境访问等不同场景。</td></tr><tr><td>计费方式</td><td><br>- 带宽计费：按照网络带宽大小来收取费用的一种计费模式，带宽越大，费用越高；<br>- 流量计费：按 VPS 实例运行期间实际产生的流量计算费用。</td></tr><tr><td>带宽</td><td>网络线路在单位时间内能够传输的数据总量。带宽数值越大表示传输能力越强，即在单位时间内传输的数据量越多。</td></tr><tr><td>IP数量</td><td>默认配置 1 个公网 IP，支持额外配置。</td></tr><tr><td>高防IP</td><td>指具备 DDoS 攻击防护能力的独立公网 IP 地址。可根据业务需求自主选择。</td></tr><tr><td>站群IP</td><td>一组独立的公网 IP 地址，适合搭建多站点业务，可避免单 IP 风险，提升多站点的搜索引擎友好度。</td></tr><tr><td>登录方式</td><td>支持选择密码登录或更安全的密钥登录。</td></tr></tbody></table></li><li><p>附加信息配置</p><p>根据您的业务需求，选择是否开启自动续费的开关。若开启系统将自动从您的账户余额扣款续费；否则到期后服务将暂停。</p></li><li><p>选择付款周期</p><p>选择服务的购买时长，支持月付、季度付、半年付和年付。</p></li><li><p>设置服务器数量</p><p>调整购买服务器的台数。</p></li><li><p>完成配置填写后，单击<strong>立即购买</strong>。</p><p><img src="'+c+'" alt="立即购买vps11.png"></p></li><li><p>在确认产品页面支持选择优惠券（若有）和输入备注信息；确认没有问题后，勾选<strong>我已阅读并同意</strong>服务条款，单击<strong>结算</strong>。</p><p><img src="'+m+'" alt="vps确认信息11.png"></p></li><li><p>在<strong>支付</strong>页面，选择某一个付款方式支付或者使用余额支付。</p><p><img src="'+P+'" alt="vps支付.png"></p></li><li><p>支付完成后如下图所示。</p><p><img src="'+S+'" alt="vps完成结算.png"></p></li></ol><hr><h3 id="操作结果" tabindex="-1">操作结果 <a class="header-anchor" href="#操作结果" aria-label="Permalink to &quot;操作结果&quot;">​</a></h3><ol><li><p>返回控制台，在左侧导航<strong>产品管理</strong>区域单击 <strong>VPS</strong>，进入<strong>我的产品与服务</strong>页面。</p></li><li><p>选择<strong>地区</strong>或<strong>状态</strong>，或在搜索框中输入需要查找的 VPS 信息。当目标 VPS 的状态由<strong>审核中</strong>变为<strong>有效的</strong>时，即可以正常使用此 VPS 。</p><p><img src="'+_+'" alt="有效的vps改版后.png"></p></li></ol><hr><h3 id="后续操作" tabindex="-1">后续操作 <a class="header-anchor" href="#后续操作" aria-label="Permalink to &quot;后续操作&quot;">​</a></h3><p>开通 VPS 成功后，您可以开始使用 VPS 。详细内容可参考<a href="./login.html">登录 VPS</a>。</p>',23)])])}const q=s(B,[["render",b]]);export{f as __pageData,q as default};
